PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://w3.org/ns/ldi-ref#>
SELECT ?ts ?point ?label ?class WHERE {
  ?point ref:hasTimeseriesId ?ts .
  FILTER (regex(str(?point), "Core_ZN", "i"))
  OPTIONAL { ?point rdfs:label ?label }
  OPTIONAL { ?point a ?class }
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://w3.org/ns/ldi-ref#>
SELECT ?ts ?point ?class WHERE {
  ?point ref:hasTimeseriesId ?ts .
  ?point a ?class .
} LIMIT 50

